def publish(bus, topic, payload):
    delivered = 0
    for fn in bus.subscribers.get(topic, []):
        try:
            fn(payload)
            delivered += 1
        except Exception:
            pass
    for fn in bus.subscribers.get("*", []):
        try:
            fn(topic, payload)
            delivered += 1
        except Exception:
            pass
    if delivered == 0:
        bus.dead_letters.append((topic, payload))
    return delivered
